// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    Attacker attacker;

    function setUp() public {
        c = new MyContract();
        attacker = new Attacker(c);
    }

    function testFuzz_property(uint256 amount, bool shouldFail) public {
        vm.assume(amount > 0);
        amount = bound(amount, 1, type(uint256).max / 2);

        // fund the contract itself so it can pay out `amount`
        vm.deal(address(c), amount);
        uint256 before = address(c).balance;
        attacker.setShouldFail(shouldFail);

        bool ok;
        // test contract is the owner (deployer), so no prank needed for the first hop
        try c.sendTo(address(attacker), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: if sendTo did NOT revert, the recipient must have
        // actually received exactly `amount` (and c's balance dropped by it).
        // The reference always reverts against this adversary or pays fully;
        // the mutant swallows the failed call's flag and 'succeeds' paying nothing.
        assertTrue(
            !ok || (address(c).balance == before - amount && attacker.got() == amount),
            "non-reverting sendTo must pay the recipient exactly amount"
        );
    }
}

contract Attacker {
    MyContract public immutable c;
    bool public shouldFail;
    bool private entered;
    uint256 public got;

    constructor(MyContract _c) {
        c = _c;
    }

    function setShouldFail(bool f) external {
        shouldFail = f;
    }

    receive() external payable {
        if (shouldFail) {
            revert("refuse payment");
        }
        got += msg.value;
        if (!entered) {
            entered = true;
            // re-enter exactly once: this reverts (we are not the owner),
            // which under `transfer` (reference) aborts the outer sendTo,
            // but under unchecked `call` (mutant) is silently swallowed.
            c.sendTo(address(this), msg.value);
        }
    }
}
